// NewTemporaryAccessPayload builds a identity service temporary_access
// endpoint payload.
func NewTemporaryAccessPayload(cookie string) *identity.TemporaryAccessPayload {
	v := &identity.TemporaryAccessPayload{}
	v.Cookie = cookie

	return v
}

// NewRequestTemporaryAccessPayload builds a identity service
// request_temporary_access endpoint payload.
func NewRequestTemporaryAccessPayload(body *RequestTemporaryAccessRequestBody, cookie string) *identity.RequestTemporaryAccessPayload {
	v := &identity.RequestTemporaryAccessPayload{
		Minutes: *body.Minutes,
		Reason:  *body.Reason,
	}
	v.Grants = make([]*identity.PermissionGrant, len(body.Grants))
	for i, val := range body.Grants {
		if val == nil {
			v.Grants[i] = nil
			continue
		}
		v.Grants[i] = unmarshalPermissionGrantRequestBodyToIdentityPermissionGrant(val)
	}
	v.Cookie = cookie

	return v
}

// NewReviewTemporaryAccessPayload builds a identity service
// review_temporary_access endpoint payload.
func NewReviewTemporaryAccessPayload(body *ReviewTemporaryAccessRequestBody, id int64, cookie string) *identity.ReviewTemporaryAccessPayload {
	v := &identity.ReviewTemporaryAccessPayload{
		Minutes:  *body.Minutes,
		Decision: *body.Decision,
		Note:     *body.Note,
	}
	v.Grants = make([]*identity.PermissionGrant, len(body.Grants))
	for i, val := range body.Grants {
		if val == nil {
			v.Grants[i] = nil
			continue
		}
		v.Grants[i] = unmarshalPermissionGrantRequestBodyToIdentityPermissionGrant(val)
	}
	v.ID = id
	v.Cookie = cookie

	return v
}

